pages["roi"] = ("roi","/roi-calculator/","Growth / ROI Calculator — FODO","Illustrative growth scenario calculator in INR. Not a guarantee.",
 hero("Growth Lab · Calculator","Growth calculator.","Change any input and the scenario updates. Illustrative estimate only — not a guarantee.","")+
 """<section><div class="container grid g2"><form id="roi-form" class="panel hud" onsubmit="return false">
<div class="field"><label for="scenario">Scenario</label><select id="scenario" name="scenario"><option value="leads">Leads / enquiries</option><option value="sales">Sales / orders</option></select></div>
<div class="field"><label for="spend">Monthly ad spend (₹)</label><div class="range-row"><input type="range" id="spend" name="spend" min="0" max="1000000" step="5000" value="50000"><input type="number" name="spend_n" min="0" max="10000000" value="50000" aria-label="Monthly ad spend in rupees"></div></div>
<div class="field"><label for="visitors">Monthly visitors (or clicks)</label><input type="number" id="visitors" name="visitors" min="0" value="5000"></div>
<div class="field"><label for="cr">Conversion rate (%)</label><input type="number" id="cr" name="cr" min="0" max="100" step="0.1" value="2"></div>
<div class="field"><label for="value">Average value per lead / order (₹)</label><input type="number" id="value" name="value" min="0" value="2000"></div>
<div class="field"><label for="industry">Industry</label><select id="industry" name="industry"><option>E-commerce</option><option>Services</option><option>SaaS</option><option>Real Estate</option><option>Local Business</option><option>Other</option></select></div>
<div class="field"><label for="lift">Assumed conversion-rate lift (%) — <span class="signal">editable assumption, not a FODO result</span></label><input type="number" id="lift" name="lift" min="0" max="300" value="20"><span class="help">Conservative examples: 10–30%. Change it to your own belief.</span></div></form>
<div id="roi-out"><div class="kpi"><div class="panel"><span class="label muted">Current / month</span><div class="big" data-k="conv">—</div><div class="mono" data-k="val"></div></div><div class="panel"><span class="label muted">Projected (illustrative)</span><div class="big signal" data-k="pconv">—</div><div class="mono" data-k="pval"></div></div><div class="panel"><span class="label muted">Estimated difference</span><div class="big" data-k="diff" style="font-size:24px">—</div></div><div class="panel"><span class="label muted">ROAS (value ÷ spend)</span><div class="big" data-k="roas" style="font-size:24px">—</div></div></div>
<div class="panel" style="margin-top:16px"><span class="tag">ILLUSTRATIVE</span><div style="display:flex;gap:24px;align-items:flex-end;height:140px;margin-top:12px" aria-hidden="true"><div style="flex:1;background:var(--line-3);height:50%" data-bar="cur"></div><div style="flex:1;background:var(--signal);height:60%" data-bar="proj"></div></div><p class="mono muted" style="font-size:11px;margin-top:8px">Left: current · Right: projected scenario</p></div>
<p class="notice">Illustrative estimate only — not a guarantee. Actual outcomes depend on offer, market, budget, tracking, execution and other factors.</p>
<div class="btn-row"><a class="btn" id="roi-discuss" data-route="audit" href="#">Discuss my numbers</a><a class="btn ghost" id="roi-wa" data-wa href="#" target="_blank" rel="noopener noreferrer">WhatsApp the summary</a></div>
<div class="acc" style="margin-top:16px"><button type="button" aria-expanded="false" aria-controls="howcalc">How this is calculated</button><div class="acc-body" id="howcalc" hidden>Current conversions = visitors × conversion rate. Current value = conversions × value per conversion. Projected conversion rate = current rate × (1 + assumed lift), capped at 100%. Projected conversions and value are recomputed the same way. Difference = projected value − current value. ROAS = value ÷ spend, shown only when spend &gt; 0. Inputs are clamped to sensible ranges; negatives and non-numbers are ignored. No FODO pricing is included.</div></div></div></div></section>""",1,"",("lab","tools"))
