def LD(*objs):
    return "".join(f'<script type="application/ld+json">{json.dumps(o, ensure_ascii=False)}</script>' for o in objs)
def crumbs_ld(trail):
    return {"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": i + 1, "name": n, "item": SITE + u} for i, (n, u) in enumerate(trail)]}
def crumbs_nav(trail, depth):
    up = "../" * depth
    parts = [f'<a href="{up}{u.lstrip("/")}">{X(n)}</a>' for n, u in trail[:-1]]
    return f'<nav class="mono muted crumbs" aria-label="Breadcrumb"><a href="{up}">Home</a> / ' + " / ".join(parts[1:] + [f'<span aria-current="page">{X(trail[-1][0])}</span>']) + '</nav>'
def faq_block(faqs, pre):
    return "".join(f'<div class="acc"><button type="button" aria-expanded="false" aria-controls="{pre}{i}">{X(q)}</button><div class="acc-body" id="{pre}{i}" hidden>{X(a)}</div></div>' for i, (q, a) in enumerate(faqs))
def faq_ld(faqs):
    return {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in faqs]}
def T(t):
    assert len(t) <= 62, t; return X(t)
